//! macOS `NSPasteboard` backup, delayed-rendering publish with read receipt, privacy markers, and
//! delayed restore (spec §7).
//!
//! Mirrors Windows' `clipboard.rs`:
//! - Backs up every item and pasteboard type up to `CLIPBOARD_BACKUP_MAX_FORMAT_BYTES`.
//! - Publishes Wren's UTF-8 text via `NSPasteboardItemDataProvider` (delayed rendering) tagged with
//!   `org.nspasteboard.TransientType`, `org.nspasteboard.ConcealedType`, and
//!   `org.nspasteboard.AutoGeneratedType` so macOS clipboard managers keep dictated text out of
//!   clipboard history AND Wren gets a genuine read receipt when the target app consumes `⌘V`.
//! - Holds the clipboard transaction lock across the entire paste so concurrent `copy_text` calls
//!   cannot interleave between `Transaction::start` and `send_cmd_v`.
//! - Restores the previous pasteboard contents `CLIPBOARD_RESTORE_MS` after a confirmed paste ONLY
//!   if `NSPasteboard.changeCount` has not advanced (no other app copied meanwhile).
//! - Exposes [`flush`] so quitting Wren restores any pending clipboard backup before exiting.

use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread::JoinHandle;
use std::time::{Duration, Instant};

use anyhow::anyhow;
use objc2::rc::{Retained, autoreleasepool};
use objc2::runtime::ProtocolObject;
use objc2::{AnyThread, DefinedClass, define_class, msg_send};
use objc2_app_kit::{
    NSPasteboard, NSPasteboardItem, NSPasteboardItemDataProvider, NSPasteboardType, NSPasteboardTypeString,
    NSPasteboardWriting,
};
use objc2_foundation::{NSArray, NSCopying, NSData, NSObject, NSObjectProtocol, NSString};
use parking_lot::{Mutex, MutexGuard};

use crate::constants::{CLIPBOARD_BACKUP_MAX_FORMAT_BYTES, CLIPBOARD_RESTORE_MS};

/// Standard NSPasteboard marker types honored by macOS clipboard managers (nspasteboard.org).
const PRIVACY_MARKERS: [&str; 3] = [
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
];

// ---- Delayed-rendering provider (macOS equivalent of Windows WM_RENDERFORMAT) ----

struct ProviderIvars {
    text: String,
    rendered: Arc<AtomicBool>,
}

define_class!(
    #[unsafe(super(NSObject))]
    #[name = "WrenPasteProvider"]
    #[ivars = ProviderIvars]
    struct WrenPasteProvider;

    unsafe impl NSObjectProtocol for WrenPasteProvider {}

    unsafe impl NSPasteboardItemDataProvider for WrenPasteProvider {
        #[unsafe(method(pasteboard:item:provideDataForType:))]
        fn provide_data(&self, _pb: Option<&NSPasteboard>, item: &NSPasteboardItem, pb_type: &NSPasteboardType) {
            let iv = self.ivars();
            iv.rendered.store(true, Ordering::SeqCst);
            let ns_text = NSString::from_str(&iv.text);
            let _ = item.setString_forType(&ns_text, pb_type);
        }
    }
);

impl WrenPasteProvider {
    fn new(text: String, rendered: Arc<AtomicBool>) -> Retained<Self> {
        let this = Self::alloc().set_ivars(ProviderIvars { text, rendered });
        unsafe { msg_send![super(this), init] }
    }
}

/// Keeps an Objective-C `WrenPasteProvider` alive across threads until the clipboard restore finishes.
struct RetainedProvider(usize);

impl RetainedProvider {
    fn from_retained(p: Retained<WrenPasteProvider>) -> Self {
        Self(Retained::into_raw(p) as usize)
    }
}

impl Drop for RetainedProvider {
    fn drop(&mut self) {
        if self.0 != 0 {
            autoreleasepool(|_| unsafe {
                let _ = Retained::from_raw(self.0 as *mut WrenPasteProvider);
            });
            self.0 = 0;
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SavedItem {
    pub representations: Vec<(String, Vec<u8>)>,
}

/// Complete backup of the general pasteboard at one instant.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct Snapshot {
    pub items: Vec<SavedItem>,
}

impl Snapshot {
    pub fn capture() -> anyhow::Result<Snapshot> {
        let _lock = transaction_lock();
        Ok(capture_now())
    }

    pub fn restore(&self) -> anyhow::Result<()> {
        let _lock = transaction_lock();
        restore_now(&self.items)
    }
}

fn capture_now() -> Snapshot {
    autoreleasepool(|_| {
        let pb = NSPasteboard::generalPasteboard();
        let Some(items) = pb.pasteboardItems() else {
            return Snapshot::default();
        };
        let mut saved = Vec::new();
        for item in items.iter() {
            let types = item.types();
            let mut reps = Vec::new();
            for pb_type in types.iter() {
                let type_name = pb_type.to_string();
                // Skip transient markers on backup so restore adds fresh markers cleanly.
                if PRIVACY_MARKERS.contains(&type_name.as_str()) {
                    continue;
                }
                if let Some(data) = item.dataForType(&pb_type) {
                    let len = data.len();
                    if len > CLIPBOARD_BACKUP_MAX_FORMAT_BYTES {
                        tracing::warn!(type_name, len, "pasteboard item too large to back up; skipping");
                        continue;
                    }
                    reps.push((type_name, data.to_vec()));
                }
            }
            if !reps.is_empty() {
                saved.push(SavedItem { representations: reps });
            }
        }
        Snapshot { items: saved }
    })
}

fn restore_now(items: &[SavedItem]) -> anyhow::Result<()> {
    autoreleasepool(|_| {
        let pb = NSPasteboard::generalPasteboard();
        pb.clearContents();
        if items.is_empty() {
            return Ok(());
        }
        let mut pb_items: Vec<Retained<NSPasteboardItem>> = Vec::with_capacity(items.len());
        for (idx, saved) in items.iter().enumerate() {
            let item = NSPasteboardItem::new();
            // Mark the restored clipboard as transient on the first item so clipboard managers don't
            // record a duplicate entry when Wren puts the user's previous copy back.
            if idx == 0 {
                let empty = NSData::new();
                let transient = NSString::from_str("org.nspasteboard.TransientType");
                let _ = item.setData_forType(&empty, &transient);
            }
            for (type_name, bytes) in &saved.representations {
                let t = NSString::from_str(type_name);
                let data = NSData::with_bytes(bytes);
                let _ = item.setData_forType(&data, &t);
            }
            pb_items.push(item);
        }
        let objects: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> = pb_items
            .into_iter()
            .map(ProtocolObject::from_retained)
            .collect();
        let array = NSArray::from_retained_slice(&objects);
        if !pb.writeObjects(&array) {
            return Err(anyhow!("NSPasteboard::writeObjects failed during restore"));
        }
        Ok(())
    })
}

/// Publish plain UTF-8 text eagerly with clipboard-manager privacy markers.
fn publish_plain_text(text: &str) -> anyhow::Result<isize> {
    autoreleasepool(|_| {
        let pb = NSPasteboard::generalPasteboard();
        pb.clearContents();

        let item = NSPasteboardItem::new();
        let ns_text = NSString::from_str(text);
        let ok = unsafe { item.setString_forType(&ns_text, NSPasteboardTypeString) };
        if !ok {
            return Err(anyhow!("NSPasteboardItem::setString_forType failed"));
        }
        let empty = NSData::new();
        for marker in PRIVACY_MARKERS {
            let t = NSString::from_str(marker);
            let _ = item.setData_forType(&empty, &t);
        }

        let obj: Retained<ProtocolObject<dyn NSPasteboardWriting>> = ProtocolObject::from_retained(item);
        let array = NSArray::from_retained_slice(&[obj]);
        if !pb.writeObjects(&array) {
            return Err(anyhow!("NSPasteboard::writeObjects failed"));
        }
        Ok(pb.changeCount())
    })
}

/// Publish UTF-8 text via delayed rendering (`NSPasteboardItemDataProvider`) so Wren gets a
/// genuine read receipt when the target app consumes `⌘V`.
fn publish_promised_text(text: &str) -> anyhow::Result<(isize, Arc<AtomicBool>, RetainedProvider)> {
    autoreleasepool(|_| {
        let pb = NSPasteboard::generalPasteboard();
        pb.clearContents();

        let rendered = Arc::new(AtomicBool::new(false));
        let provider = WrenPasteProvider::new(text.to_string(), rendered.clone());
        let proto: &ProtocolObject<dyn NSPasteboardItemDataProvider> = ProtocolObject::from_ref(&*provider);

        let item = NSPasteboardItem::new();
        let str_type: Retained<NSPasteboardType> = unsafe { NSPasteboardTypeString.copy() };
        let types = NSArray::from_retained_slice(&[str_type]);
        if !item.setDataProvider_forTypes(proto, &types) {
            return Err(anyhow!("NSPasteboardItem::setDataProvider_forTypes failed"));
        }
        let empty = NSData::new();
        for marker in PRIVACY_MARKERS {
            let t = NSString::from_str(marker);
            let _ = item.setData_forType(&empty, &t);
        }

        let obj: Retained<ProtocolObject<dyn NSPasteboardWriting>> = ProtocolObject::from_retained(item);
        let array = NSArray::from_retained_slice(&[obj]);
        if !pb.writeObjects(&array) {
            return Err(anyhow!("NSPasteboard::writeObjects failed"));
        }
        Ok((pb.changeCount(), rendered, RetainedProvider::from_retained(provider)))
    })
}

// ---- Pending-restore coordination ----

struct PendingRestore {
    flush_now: Arc<AtomicBool>,
    handle: JoinHandle<()>,
}

static PENDING: Mutex<Option<PendingRestore>> = Mutex::new(None);
static TX_MUTEX: Mutex<()> = Mutex::new(());

/// Held for any write to the general pasteboard so it can never interleave with a dictation paste.
pub(crate) fn transaction_lock() -> MutexGuard<'static, ()> {
    flush();
    TX_MUTEX.lock()
}

/// If a previous paste is still waiting to restore the clipboard, restore it right now and wait
/// for the worker thread to finish. Called on Wren quit and before any new clipboard operation.
pub fn flush() {
    let pending = PENDING.lock().take();
    if let Some(p) = pending {
        p.flush_now.store(true, Ordering::SeqCst);
        let _ = p.handle.join();
    }
}

/// Copy `text` to the general pasteboard, marked out of clipboard managers.
pub fn copy_text(text: &str) -> anyhow::Result<()> {
    if text.is_empty() {
        return Err(anyhow!("nothing to copy"));
    }
    let _lock = transaction_lock();
    publish_plain_text(text)?;
    Ok(())
}

/// Active paste transaction: holds `TX_MUTEX` until finalized (`leave_text`, `restore_later`, or
/// `Drop`) so no concurrent copy can overwrite the pasteboard before `⌘V` lands.
pub struct Transaction {
    _guard: Option<MutexGuard<'static, ()>>,
    text: String,
    backup: Snapshot,
    own_change_count: isize,
    rendered: Arc<AtomicBool>,
    provider: Option<RetainedProvider>,
    finished: bool,
}

impl Transaction {
    pub fn start(text: &str) -> anyhow::Result<Self> {
        let guard = transaction_lock();
        let backup = capture_now();
        let (own_change_count, rendered, provider) = publish_promised_text(text)?;
        Ok(Self {
            _guard: Some(guard),
            text: text.to_string(),
            backup,
            own_change_count,
            rendered,
            provider: Some(provider),
            finished: false,
        })
    }

    /// Wait up to `timeout` for the target app to read the promised UTF-8 text from the pasteboard.
    pub fn wait_for_read(&self, timeout: Duration) -> bool {
        let deadline = Instant::now() + timeout;
        while !self.rendered.load(Ordering::SeqCst) {
            if Instant::now() >= deadline {
                return false;
            }
            std::thread::sleep(Duration::from_millis(8));
        }
        true
    }

    /// Leave Wren's text on the clipboard (e.g. `NotRead`, `FocusChanged`, or paste failed).
    /// Materialises the plain text eagerly so it remains pasteable after the provider is dropped.
    pub fn leave_text(mut self) {
        self.finished = true;
        let _ = publish_plain_text(&self.text);
        self.provider.take();
        self._guard.take();
    }

    /// Schedule the backup to be restored after `CLIPBOARD_RESTORE_MS`, unless another app wrote
    /// to the pasteboard in the meantime (`changeCount` changed).
    pub fn restore_later(mut self) {
        self.finished = true;
        let backup = Arc::new(std::mem::take(&mut self.backup));
        let backup_for_thread = backup.clone();
        let provider = self.provider.take();
        let expected_count = self.own_change_count;
        let flush_now = Arc::new(AtomicBool::new(false));
        let f = flush_now.clone();

        // Release TX_MUTEX before spawning the worker so the worker can lock TX_MUTEX when it
        // performs the restore (and ensure any stale PENDING handle is joined first).
        self._guard.take();
        flush();

        let spawned = std::thread::Builder::new().name("wren-clipboard-restore".into()).spawn(move || {
            let _keep_provider_alive = provider;
            let deadline = Instant::now() + Duration::from_millis(CLIPBOARD_RESTORE_MS);
            while Instant::now() < deadline {
                if f.load(Ordering::SeqCst) {
                    break;
                }
                std::thread::sleep(Duration::from_millis(15));
            }
            let _lock = TX_MUTEX.lock();
            autoreleasepool(|_| {
                let pb = NSPasteboard::generalPasteboard();
                if should_restore(pb.changeCount(), expected_count) {
                    if let Err(err) = restore_now(&backup_for_thread.items) {
                        tracing::warn!(error = %err, "failed to restore macOS pasteboard");
                    }
                } else {
                    tracing::debug!("pasteboard changed after paste; keeping user's newer copy");
                }
            });
        });

        match spawned {
            Ok(handle) => {
                *PENDING.lock() = Some(PendingRestore { flush_now, handle });
            }
            Err(err) => {
                tracing::warn!(error = %err, "cannot spawn clipboard restore thread; restoring now");
                std::thread::sleep(Duration::from_millis(CLIPBOARD_RESTORE_MS));
                let _lock = TX_MUTEX.lock();
                autoreleasepool(|_| {
                    let pb = NSPasteboard::generalPasteboard();
                    if should_restore(pb.changeCount(), expected_count) {
                        let _ = restore_now(&backup.items);
                    }
                });
            }
        }
    }
}

impl Drop for Transaction {
    fn drop(&mut self) {
        if !self.finished {
            // `_guard` is still held while `Drop` runs before field drops.
            autoreleasepool(|_| {
                let pb = NSPasteboard::generalPasteboard();
                if should_restore(pb.changeCount(), self.own_change_count) {
                    let _ = restore_now(&self.backup.items);
                }
            });
        }
    }
}

/// Pure decision: only restore if nobody else modified the pasteboard since Wren published.
pub fn should_restore(current_change_count: isize, own_change_count: isize) -> bool {
    current_change_count == own_change_count
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn restore_only_runs_when_change_count_matches() {
        assert!(should_restore(42, 42));
        assert!(!should_restore(43, 42));
        assert!(!should_restore(41, 42));
    }

    #[test]
    fn copy_text_rejects_empty() {
        assert!(copy_text("").is_err());
    }
}
